#pragma once
#include <type_traits>
#include <jni/jni.h>
#include "../util/fixed_string.hpp"
#include "object.hpp"
#include "wrap.hpp"

#if defined(_MSC_VER)
#define JABA_NO_UNIQUE_ADDRESS [[msvc::no_unique_address]]
#else
#define JABA_NO_UNIQUE_ADDRESS [[no_unique_address]]
#endif

namespace jaba
{
	// Loc of a static field, there is no instance to find
	struct static_loc { };

	// Stateless, holds nothing. Loc::owner(const void* field) walks back from the field's address
	// to the instance it lives in (generated by JABA_FIELD). ClassT is the class it is looked up on.
	template <class ValT, class ClassT, fixed_string Mapping, class Loc>
	class field : public mapped<Mapping>
	{
	public:
		static constexpr bool is_static = std::is_same_v<Loc, static_loc>;

		using mapped<Mapping>::mapping;

		[[nodiscard]] static jfieldID native();

		[[nodiscard]] ValT get() const;
		void set(ValT val);

		[[nodiscard]] operator ValT() const
		{
			return get();
		}

		field& operator=(ValT val)
		{
			set(val);
			return *this;
		}

		struct val_holder
		{
			ValT val;

			[[nodiscard]] ValT* operator->() noexcept
			{
				return &val;
			}
		};

		[[nodiscard]] val_holder operator->() const
		{
			return { get() };
		}

	private:
		[[nodiscard]] jobject self() const noexcept
		{
			return Loc::owner(this).obj();
		}
	};

	template <class ValT, class ClassT, fixed_string Mapping>
	using static_field = field<ValT, ClassT, Mapping, static_loc>;
}

#include "field.inl"
